// Generated by warp.py: output frame -> source frame, piecewise linear (source = the original 48 s cut).
export const WARP: [number, number][] = [[0, 0], [112, 112], [172, 172], [224, 237], [252, 272], [256, 277], [294, 346], [296, 349], [336, 469], [364, 526], [366, 530], [392, 565], [434, 666], [436, 671], [462, 750], [486, 846], [506, 868], [508, 876], [532, 906], [534, 909], [588, 1071], [590, 1077], [630, 1190], [654, 1215], [710, 1274], [730, 1296], [732, 1299], [756, 1327], [758, 1330], [826, 1456], [828, 1460], [896, 1571], [898, 1574], [930, 1672], [956, 1720], [974, 1740], [978, 1748], [1004, 1974], [1013, 2007], [1078, 2232], [1080, 2239], [1162, 2468], [1204, 2586], [1206, 2591], [1252, 2729], [1260, 2749], [1262, 2754], [1280, 2780], [1304, 2827], [1376, 2899], [1440, 2963]];
export const OUT_DURATION = 2963;
export const srcAt = (fo: number) => {
  for (let i = 1; i < WARP.length; i++) {
    const [s0, o0] = WARP[i - 1];
    const [s1, o1] = WARP[i];
    if (fo < o1 || i === WARP.length - 1) return s0 + ((fo - o0) * (s1 - s0)) / (o1 - o0);
  }
  return fo;
};
// source frames per output frame (1 = original speed)
export const rateAt = (fo: number) => {
  for (let i = 1; i < WARP.length; i++) if (fo < WARP[i][1] || i === WARP.length - 1) return (WARP[i][0] - WARP[i - 1][0]) / (WARP[i][1] - WARP[i - 1][1]);
  return 1;
};
// output frame of a source frame
export const outAt = (fs: number) => {
  for (let i = 1; i < WARP.length; i++) {
    const [s0, o0] = WARP[i - 1];
    const [s1, o1] = WARP[i];
    if (fs < s1 || i === WARP.length - 1) return o0 + ((fs - s0) * (o1 - o0)) / (s1 - s0);
  }
  return fs;
};
